import { FOOD_LIST_FILTERS, type FoodItem, type FoodListFilter } from '@motivation/shared';
import { HealthService } from '../../../services/health.service.js';
import { navigate } from '../../../router.js';
import { buildSectionPage } from '../../../utils/section-page.utils.js';
import { documentStyleSheet } from '../../../utils/css.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { safeExec } from '../../../utils/safe-exec.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../../_shared/screen-status.js';
import { HEALTH_EVENTS, type FoodCardSelectEvent } from '../health-events.js';
import '../nutrition/food-card/food-card.component.js';
import type { FoodCard } from '../nutrition/food-card/food-card.component.js';
import themeStyles from '../health-theme.css?inline';
import screenStyles from './health-foods-screen.css?inline';

documentStyleSheet(themeStyles);
documentStyleSheet(screenStyles);

const FILTER_LABELS: Record<FoodListFilter, string> = { all: 'All', to_check: 'To check', archived: 'Archived' };
const TYPE_DELAY_MS = 200;

const template = document.createElement('template');
template.innerHTML = `
    <div class="foods">
        <div class="foods-head">
            <input type="search" class="foods-query" placeholder="Search foods" aria-label="Search foods" autocomplete="off">
            <button type="button" class="foods-new">+ New food</button>
        </div>
        <div class="foods-filters" role="tablist">
            ${FOOD_LIST_FILTERS.map((f) => `<button type="button" role="tab" data-filter="${f}">${FILTER_LABELS[f]}</button>`).join('')}
        </div>
        <div class="foods-list" role="list"></div>
        <p class="foods-empty" hidden></p>
    </div>
`;

/**
 * Story 423 — the food library (`/health/foods`, 418 #13): every food as a `<food-card>`, A–Z,
 * searchable by name, in three lists — all, to check (made by an AI estimate or a label read), and
 * archived. A card opens the food's editor; "+ New food" makes one. `?filter=` keeps the list.
 */
export class HealthFoodsScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private filterValue: FoodListFilter = 'all';
    private typing: ReturnType<typeof setTimeout> | null = null;
    private loadSequence = 0;
    private readonly log = createComponentLogger('health-foods-screen');
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    set query(value: URLSearchParams) {
        const f = value.get('filter') ?? 'all';
        if (!(FOOD_LIST_FILTERS as readonly string[]).includes(f)) throw new Error(`Unknown food list "${f}" — expected one of ${FOOD_LIST_FILTERS.join(', ')}.`);
        this.filterValue = f as FoodListFilter;
    }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;
        const page = buildSectionPage(this, 'Foods', 'health', '/health');
        const body = template.content.cloneNode(true) as DocumentFragment;
        this.statusNodes.retryNode.addEventListener('click', () => void this.load());
        page.content.append(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode, body);

        this.querySelector('.foods-new')!.addEventListener('click', () => navigate('/health/foods/new'));
        for (const b of this.querySelectorAll<HTMLButtonElement>('[data-filter]')) {
            b.addEventListener('click', () => {
                this.filterValue = b.dataset.filter as FoodListFilter;
                // The list is navigation-worthy: a reload or Back lands on it. Silent, so the screen stays.
                const path = this.filterValue === 'all' ? '/health/foods' : `/health/foods?filter=${this.filterValue}`;
                navigate(path, { history: 'replace', silent: true });
                void this.load();
            });
        }
        this.querySelector('.foods-query')!.addEventListener('input', () => {
            if (this.typing !== null) clearTimeout(this.typing);
            this.typing = setTimeout(() => void this.load(), TYPE_DELAY_MS);
        });
        this.addEventListener(HEALTH_EVENTS.FOOD_CARD_SELECT, (e: FoodCardSelectEvent) => {
            const { entry } = e.detail;
            if (entry.kind === 'food') navigate(`/health/foods/${encodeURIComponent(entry.item.id)}`);
        });
        void this.load();
    }

    disconnectedCallback(): void {
        if (this.typing !== null) clearTimeout(this.typing);
    }

    private async load(): Promise<void> {
        const sequence = ++this.loadSequence;
        for (const b of this.querySelectorAll<HTMLButtonElement>('[data-filter]')) {
            b.setAttribute('aria-selected', String(b.dataset.filter === this.filterValue));
        }
        const q = (this.querySelector('.foods-query') as HTMLInputElement).value.trim();
        return safeExec(this, this.log, async () => {
            const foods = await HealthService.listFoodItems(this.filterValue, q);
            if (sequence !== this.loadSequence) return;
            this.render(foods, q);
        }, { silent: true, errorMessage: 'Could not load the food library' });
    }

    private render(foods: FoodItem[], q: string): void {
        const list = this.querySelector('.foods-list') as HTMLElement;
        list.replaceChildren(...foods.map((item) => {
            const card = document.createElement('food-card') as FoodCard;
            card.setAttribute('role', 'listitem');
            card.entry = { kind: 'food', item };
            return card;
        }));
        const empty = this.querySelector('.foods-empty') as HTMLElement;
        empty.hidden = foods.length > 0;
        empty.textContent = q ? `No food called “${q}” here.` : this.filterValue === 'all' ? 'No foods yet.' : `Nothing ${FILTER_LABELS[this.filterValue].toLowerCase()}.`;
    }
}

if (!customElements.get('health-foods-screen')) {
    customElements.define('health-foods-screen', HealthFoodsScreen);
}
